mapper.select:
select count(1) as peerCount, round(avg(t.avg_score), 2) as peerAvgScore, round(avg(t.gpa), 2) as peerAvgGpa
from (
    select g.student_id, round(avg(g.total_score), 2) as avg_score,
           round(sum(case when g.grade_point is not null then g.grade_point * ifnull(cl.credit,0) else 0 end)
                 / nullif(sum(case when g.grade_point is not null then ifnull(cl.credit,0) else 0 end), 0), 2) as gpa
    from aem_grade_record g
    join sam_student s on s.student_id = g.student_id
    left join tpm_course_library cl on cl.course_id = g.course_id
    where g.status = '0'
      and s.major_id = #{majorId}
       and s.enrollment_year = #{enrollmentYear}
    group by g.student_id
) t

select e.course_id as courseId, count(1) as evalCount, round(avg(e.total_score), 2) as avgScore from aem_evaluation_result e where e.status = '0' and e.course_id is not null and e.total_score is not null and e.course_id in
#{courseId}
group by e.course_id
